for (const entry of [
  { label: "legacy missing version", method: "GET" },
  { label: "explicit v1", method: "GET", version: "runner.http.v1" },
  { label: "legacy unsupported method", method: "PUT" },
  { label: "explicit v1 unsupported method", method: "PUT", version: "runner.http.v1" },
] as const) {
  test(`stored HTTP ${entry.label} keeps its implementation, method and nested pin during ordinary edits`, async () => {
    const flow = fixture();
    if (!flow.plan?.graph) throw new Error("Missing fixture graph");
    const original = {
      id: "stored_http",
      kind: "action" as const,
      actionType: "http" as const,
      agentId: "reporter",
      inputKeys: [],
      outputKey: "http_result",
      next: "end",
      actionUrl: "https://example.test/original",
      actionMethod: entry.method,
      ...("version" in entry ? { executionVersion: entry.version } : {}),
    };
    flow.plan.graph.nodes.push(original);
    const requests: { method: string; body: { revision: number; plan: WakerFlowPlan } }[] = [];
    let saved: WakerFlow | undefined;
    globalThis.fetch = (async (_path, init) => {
      const body = JSON.parse(String(init?.body));
      requests.push({ method: init?.method ?? "GET", body });
      return Response.json({ flow: { ...flow, plan: body.plan, revision: 4 } });
    }) as typeof fetch;
    const { view, user } = draw(flow, (value) => {
      saved = value;
    });
    const methods = view.getByRole("combobox", { name: "节点4HTTP方法" });
    expect(Array.from(methods.querySelectorAll("option"), (option) => option.textContent)).toEqual(
      entry.method === "PUT" ? ["PUT（不支持，未就绪）", "GET", "POST"] : ["GET", "POST"],
    );
    if (!("version" in entry) || entry.method === "PUT") {
      expect(view.getByRole("status").textContent).toContain("保存不会自动升级，不能执行");
    }
    await user.clear(view.getByRole("textbox", { name: "节点4HTTP URL" }));
    await user.type(
      view.getByRole("textbox", { name: "节点4HTTP URL" }),
      "https://example.test/edited",
    );
    await user.click(view.getByRole("button", { name: "确认保存计划" }));
    expect(requests).toHaveLength(1);
    expect(requests[0]?.method).toBe("PUT");
    expect(requests[0]?.body.revision).toBe(3);
    const expected = { ...original, actionUrl: "https://example.test/edited" };
    expect(requests[0]?.body.plan.graph?.nodes[3]).toEqual(expected);
    expect(saved?.plan?.graph?.nodes[3]).toEqual(expected);
    expect(Object.hasOwn(expected, "executionVersion")).toBe("version" in entry);
    expect(requests[0]?.body.plan.graph?.nodes[2]).toMatchObject({
      kind: "flow",
      targetWakerflowId: childId,
      targetRevision: 2,
    });
  });
}
